WITH inventory_by_product AS (SELECT product_id, ROUND(STDDEV(quantity), 2) AS stddev_quantity, MAX(last_restock) AS last_last_restock FROM inventory WHERE MONTH(last_restock) IN (1, 10, 12) GROUP BY product_id) SELECT p.launch_date, p.brand, ibp.stddev_quantity, ibp.last_last_restock FROM products p INNER JOIN inventory_by_product ibp ON p.id = ibp.product_id WHERE ibp.stddev_quantity > 35
